window.STORY_CHAPTERS["c43078d6f77bb9f9b"]={"id":"c43078d6f77bb9f9b","lines":[{"uid":"talk.vc.home_time_suguha_1st_4#originalText","id":"talk.vc.home_time_suguha_1st_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天的午餐要怎么解决？要不要偶尔一起吃午餐？","en":"What do you want to do for lunch today? Wanna eat together for a change?","ja":"今日のお昼はどうする?たまには一緒に食べようか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_1st_7#originalText","id":"talk.vc.home_time_suguha_1st_7","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"哇──星星好美喔！你看你看，有流星！","en":"Oooh, the stars are so pretty! Look! It's a shooting star!","ja":"うわー、星がきれい!見て見て、流れ星!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_1st_10#originalText","id":"talk.vc.home_time_suguha_1st_10","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"半夜醒来时，只要看见有你在……就令我很安心。","en":"Whenever I wake up in the middle of the night, I always feel safe...when I see you.","ja":"夜中、目が覚めて君がいると……安心するんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_suguha_1st_1#originalText","id":"talk.vc.home_day_suguha_1st_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"星期一会觉得郁闷，都是错在星期天过得太开心！","en":"Yeah, Mondays wouldn't be so hard on you if you didn't party so hard on Sundays!","ja":"月曜日が辛いのは日曜日が楽しすぎるのがいけないんだよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_suguha_1st_2#originalText","id":"talk.vc.home_day_suguha_1st_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"平日我有社团活动要忙……所以也常常没时间登录呢。","en":"I'm so busy with my after-school club that I can't log in much on weekdays.","ja":"平日は部活が忙しくて……なかなかログインできないことも多いんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_suguha_1st_3#originalText","id":"talk.vc.home_day_suguha_1st_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"假日到啦～你已经决定今天要做什么了吗？我还没有任何安排喔！","en":"Weee, finally a day off! Got any plans today? I'm totally free!","ja":"お休みだー今日の予定は決まってる?あたしは、何にもないよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_suguha_1st_4#originalText","id":"talk.vc.home_day_suguha_1st_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天也好开心呢。好好睡个觉之后，明天又得早起了。","en":"I had a lot of fun today. I'd better turn in early so I can wake up early again tomorrow.","ja":"今日も楽しかったねゆっくり寝て、明日はまた早く起きないと"},"kind":"dialogue"},{"uid":"talk.vc.home_season_suguha_1st_1#originalText","id":"talk.vc.home_season_suguha_1st_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"天气开始变暖后，在道场训练时总算比较不难受了。","en":"Now that it's warmer, training at the dojo has finally gotten a bit tough.","ja":"暖かくなって、やっと道場での稽古が辛くなくなってきたよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_suguha_1st_2#originalText","id":"talk.vc.home_season_suguha_1st_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"夏天要小心脱水。尤其玩游戏时，一定要记得补充水分！","en":"When it's summer you have to make sure to stay hydrated! Especially while you're gaming.","ja":"夏は脱水に気をつけないと特に、ゲーム中は忘れずに水分補給!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_suguha_1st_3#originalText","id":"talk.vc.home_season_suguha_1st_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"秋天的烤地瓜好诱人……反正刚训练完，吃一点点就好……","en":"It's autumn, and the roasted sweet potatoes are calling to me... Maybe a li'l one as a treat after practice.","ja":"秋は焼き芋の誘惑が……トレーニングの後だから少しだけ……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_suguha_1st_4#originalText","id":"talk.vc.home_season_suguha_1st_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天就煮火锅吧。大家一起吃，一定会从头暖到脚的！","en":"Let's have hot pot today. Nothing warms the soul quite like hot pot with good company!","ja":"今日はお鍋にしようかみんなで食べればきっと温まるよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_rain_real_wait_1#originalText","id":"talk.vc.home_rain_real_wait_1","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"欢迎您回来，主人。嘻嘻嘻，怎么样？感觉还满有那个样子的吧？","en":"Welcome home, master! Hehehe... What do you think? Did I catch your attention?","ja":"おかえりなさいませ、ご主人様えへへ、どうかな?なかなか様になってるでしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_rain_real_wait_2#originalText","id":"talk.vc.home_rain_real_wait_2","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"有朝一日想在很多粉丝的面前开演唱会呀！到时你也会来的对吧？","en":"One day I hope I can have a lot of fans to do a concert for. You'll be there too, right?","ja":"いつかたくさんのファンの前でコンサートがしたいんだぁその時はあなたも来てくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_rain_real_wait_3#originalText","id":"talk.vc.home_rain_real_wait_3","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"我的女仆艺名也叫「伶茵」，所以平常也轻松地叫我伶茵就好哦！","en":"Since the maid's name is also Rain, feel free to call me that even in the real world.","ja":"メイドさんネームも「レイン」なのだから、リアルでも気軽にレインって呼んでね"},"kind":"dialogue"},{"uid":"talk.vc.home_rain_real_wait_4#originalText","id":"talk.vc.home_rain_real_wait_4","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"嘿嘿，用真实的姿态见面什么的，虽然有点害羞但很开心呢～","en":"Hehe. I'll admit, it's a little embarrassing meeting in the real world, but I'm also excited.","ja":"ふふ、リアルの姿で会うのってちょっと恥ずかしいけど嬉しいね"},"kind":"dialogue"},{"uid":"talk.vc.home_rain_real_touch_1#originalText","id":"talk.vc.home_rain_real_touch_1","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"我在ALO里是红色头发，所以这发色有点新鲜对吧？","en":"Since my hair was red on ALO, this new color feels refreshing!","ja":"ALOだと赤い髪だからこの髪色はちょっと新鮮でしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_rain_real_touch_2#originalText","id":"talk.vc.home_rain_real_touch_2","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"你很在意胸口的缎带吗？可不能拉开哦～主人","en":"Did this ribbon catch your eye? Don't pull on it, master!","ja":"胸のリボンが気になるの?引っ張っちゃダメですよ、ご主人様"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_darkside_1#originalText","id":"talk.vc.home_wait_edith_darkside_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这真的是我的记忆……？是的话，为什么这么模糊不清？","en":"Are these really my memories? Then...why are they so fuzzy?","ja":"これは本当にあたしの記憶……?だったら、どうしてこんなにぼんやりとしているの?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_darkside_2#originalText","id":"talk.vc.home_wait_edith_darkside_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我曾经有过必须守护的事物。但是，我没有守住……","en":"I once had someone precious to me...but I couldn't protect her.","ja":"あたしには、守るべきものがあったでも、守れなかった……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_darkside_3#originalText","id":"talk.vc.home_wait_edith_darkside_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"拜托你现在别来管我。要是敢过来，别怪我手下不留情。","en":"Stay away from me if you know what's good for you. I want to be alone.","ja":"今は放っておいて近寄るなら容赦しないわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_darkside_4#originalText","id":"talk.vc.home_wait_edith_darkside_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我是集成骑士……伊迪丝‧辛赛西斯‧潭，除此之外谁都不是！","en":"I am Eydis Synthesis Ten. An Integrity Knight, and nothing more!","ja":"あたしは整合騎士……イーディス・シンセシス・テンそれ以外の、何者でもない!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_darkside_5#originalText","id":"talk.vc.home_wait_edith_darkside_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"泡澡……没错，泡澡是非常舒服的事，尤其是跟某个人一起入浴的时候……","en":"Baths... My refuge of bliss! Though they're even more blissful when I get to share them with someone...","ja":"お風呂……そう、お風呂は気持ちがいい誰かと一緒に入れば、なおさら……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_darkside_6#originalText","id":"talk.vc.home_wait_edith_darkside_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"深邃的水底没有任何会动的事物，弥漫四周的，仅有彻底的黑暗……","en":"Deep underwater... Where not much life stirs... Nothing but darkness...","ja":"深い深い水の底あたりに動く物は何もないあるのはただ、暗い闇……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_darkside_7#originalText","id":"talk.vc.home_wait_edith_darkside_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……蜘蛛？嗯，是有蜘蛛，我去的地方，总是会有……","en":"A...spider? Yes. There was a spider. She always told me where to go...","ja":"……蜘蛛?そう、蜘蛛がいたあたしが行く場所に、いつも……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_darkside_8#originalText","id":"talk.vc.home_wait_edith_darkside_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"欸，你也听到了吧？呼唤我的那个声音，一直、一直不断地在呼唤着我啊！","en":"Can't you hear that voice? It's been calling my name. Calling my name for so long...","ja":"ほら、聞こえるでしょ?あたしの名前を呼ぶ声ずっと、ずうっとあたしを呼んでるの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_darkside_9#originalText","id":"talk.vc.home_wait_edith_darkside_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"无所事事的时候，感觉自己好像会坠入黑暗里头。不过，那样或许也不错。","en":"Whenever I'm idle, I feel like I'm slipping into the darkness. But... that might be for the best.","ja":"何もしないでいると闇の中に落ちていきそうでも、それもいいのかもしれないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_darkside_1#originalText","id":"talk.vc.home_touch_edith_darkside_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这个款式的发饰，还有另一个。而某个人……曾说……跟我戴的是成对的发饰……","en":"This hair ribbon...there's another just like it. Someone...wanted to have one like mine...","ja":"この髪飾り、もうひとつあるのそれを……誰かが……あたしとお揃いだって……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_darkside_2#originalText","id":"talk.vc.home_touch_edith_darkside_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我的脑海里住着一个人。可是，那个人……我不晓得是谁……","en":"There's this girl I see inside my head. But who is she? I...have no idea.","ja":"頭の中に、誰かがいるんだでも、それが誰なのか……わからない……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_darkside_3#originalText","id":"talk.vc.home_touch_edith_darkside_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我以前有被人这样抚摸过。……不、不对，是我曾经这样抚摸过别人，那是谁？","en":"Long ago, someone patted my head like this and... No, it was me. I patted someone else's head...","ja":"昔、そうやって撫でてもらった……いえ、違うわあたしが撫でてあげたの、誰かを"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_darkside_4#originalText","id":"talk.vc.home_touch_edith_darkside_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……现在不要碰我，再碰一次，我就砍了你。","en":"Hey...don't touch me right now. If you touch me again, I'll kill you.","ja":"……今、あたしに触らないで次に触ったら、斬り捨てる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_darkside_5#originalText","id":"talk.vc.home_touch_edith_darkside_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你在担心我吗？谢谢……不过，这份痛楚，肯定是无法消解的。","en":"Aw, you're worried about me? Thanks. But...I don't think I can do anything to stop this pain.","ja":"心配してくれたの?ありがとう……でも、きっとこの痛みは、どうしようもないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_darkside_6#originalText","id":"talk.vc.home_touch_edith_darkside_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……你刚才做了什么？你该不会是碰了我吧？","en":"Did you...do something just now? I hope you weren't touching me.","ja":"……今、何かした?まさかあたしに触ったりしていないわよね?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_darkside_7#originalText","id":"talk.vc.home_touch_edith_darkside_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"心里一直乱糟糟的，不管做什么、去哪里，都平静不下来。","en":"I have this uneasy feeling in my heart that I just can't shake. No matter what I do...or where I go.","ja":"胸がずっとザワザワしてる何をしても、どこへ行っても全然治まらないの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_darkside_8#originalText","id":"talk.vc.home_touch_edith_darkside_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我得快点回去……可是，我该回去哪里才好？拜托你，告诉我。","en":"I need to get back...now. But... get back to...where, exactly? Please. Tell me.","ja":"はやく帰らなくちゃ……でも、どこへ帰ればいいの?ねえ、教えて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_1#originalText","id":"talk.vc.home_time_edith_darkside_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"早上……我好像听到了某人的声音。那声音在呼唤我的名字，一次又一次。","en":"Morning... I thought I heard someone calling me. Calling my name. Over and over.","ja":"朝……誰かの声が聞こえた気がしたのあたしの名前を、何回も"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_2#originalText","id":"talk.vc.home_time_edith_darkside_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我谁都不相信，除了告诉我这份痛楚的真相的人之外。","en":"I won't trust anyone, except the one who can tell me why I'm in so much pain.","ja":"誰も信じられないあたしに、この痛みの正体を教えてくれる人以外は"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_3#originalText","id":"talk.vc.home_time_edith_darkside_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……不用准备餐点，我没食欲。少吃个几餐不会怎样。","en":"I don't want to eat... I have no appetite. I'll be fine. It's okay to skip meals now and then.","ja":"……食事はいらない食欲がないの少しくらい食べなくても、大丈夫"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_4#originalText","id":"talk.vc.home_time_edith_darkside_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"索鲁斯的光芒是如此强烈，但是，我觉得自己心中的黑暗，在这光芒中似乎更加壮大了。","en":"Solus's light is so strong... But I feel like the darkness inside me grows even stronger in the light.","ja":"ソルスの光がこんなに強いでも、あたしの中の闇は光の中で一層強くなる気がする"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_5#originalText","id":"talk.vc.home_time_edith_darkside_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"集成骑士……从天界受召前来，守护人界的骑士们。我真的是那种骑士吗？","en":"An Integrity Knight, summoned from the heavens to guard the Human Empire... Is this really who I am?","ja":"整合騎士……天界から喚ばれた人界を守るべき騎士たち本当に、あたしがその騎士なの?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_6#originalText","id":"talk.vc.home_time_edith_darkside_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那边的孩子们笑得好开心……但为什么，我看着他们却会流泪呢？","en":"Those kids over there look so happy... So why does watching them make me cry?","ja":"あそこの子どもたち、楽しそうに笑ってるわ……なのに、どうしてあたしはそれを見て泣いてるの?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_7#originalText","id":"talk.vc.home_time_edith_darkside_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"踏入浴池，全身泡进热水的时候，会让我觉得脑袋舒服一些。","en":"Whenever I'm in a nice, warm bath, my mind seems to clear a little.","ja":"お風呂に入って温かいお湯に包まれている間は少しだけ頭がスッキリするの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_8#originalText","id":"talk.vc.home_time_edith_darkside_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真是丰盛的晚餐，一个人开动太可惜了。真想……跟某个人一起享用呢。","en":"What a feast! And what a shame to eat this all by myself. I wish... I could share it with someone.","ja":"立派な夕食ねひとりで食べるのはもったいない誰かと……食べたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_9#originalText","id":"talk.vc.home_time_edith_darkside_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"悬浮在黑暗中的月亮，就像是我的心中，那个洁白又空虚的，刺眼空洞。","en":"My heart is just like the full moon. A bright, white hole in the dark fabric of space.","ja":"闇の中に浮かぶ月はあたしの心と同じ白くぽっかりと開いた、眩しい穴"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_10#originalText","id":"talk.vc.home_time_edith_darkside_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这片黑暗……感觉真是熟悉。总觉得，心里好平静。","en":"This darkness... It's terribly familiar to me. Familiar and... somehow comforting.","ja":"この闇……すごく馴染み深いわなんだか、落ち着くの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_11#originalText","id":"talk.vc.home_time_edith_darkside_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我得快点睡……否则，会被那孩子……骂的……","en":"I need to go to sleep... Otherwise, she'll yell at me.","ja":"眠らないと……そうじゃないと、あの子に……怒られちゃうから……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_darkside_12#originalText","id":"talk.vc.home_time_edith_darkside_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"为什么我人会在这么豪华的房间……对喔，我是集成骑士。","en":"Why am I in such an ornate room?! Oh, right...I'm an Integrity Knight.","ja":"どうして、あたしはこんな立派な部屋に……そうかあたしは整合騎士、だったんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_darkside_1#originalText","id":"talk.vc.home_etc_edith_darkside_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"像这样追着目标前进，或许总有一天我会找到。找到我心中的那位无名氏。","en":"If I keep chasing my dreams I might reach her someday, the girl I see inside me.","ja":"こうして、目的を追っていけばいつかたどり着くかも知れないあたしの中の、誰かに"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_darkside_2#originalText","id":"talk.vc.home_etc_edith_darkside_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"礼物……谁给的？要是看看名字，说不定能想起什么。","en":"A gift... Who's it from? If I check the name, I might remember something.","ja":"贈り物……誰から?名前を見れば、なにかを思い出せるかもしれない"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_darkside_3#originalText","id":"talk.vc.home_etc_edith_darkside_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"又非得动身前往他处不可吗……？既然如此，就尽快解决吧。","en":"I have to go far away again? Well...let's get it done quickly.","ja":"また、どこかに行かなければならないの……?なら、さっさと済ませましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_past_1#originalText","id":"talk.vc.home_wait_edith_past_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我回来了～妳有没有当个好孩子啊？我这次有带礼物回来喔～","en":"Honey, I'm hommme! Were you good while I was gone? And I've got a souvenir for you!","ja":"ただいまーいい子にしてた?今回は、お土産があるよー"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_past_2#originalText","id":"talk.vc.home_wait_edith_past_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"为了保护妳，我必须变强才行……所以，我才会成为剑士。","en":"I need to get stronger so that I can protect you. That's why I became a swordsman.","ja":"あなたを守るためには強くならないと……だからあたしは、剣士になったの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_past_3#originalText","id":"talk.vc.home_wait_edith_past_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"虽然不放心丢下妳出门，但只要找到治疗双脚的办法，我们就能一直在一起了喔。","en":"I hate to leave you alone, but if I find a cure for your foot, I'll never have to leave you again!","ja":"あなたを残していくのは心配だけど足を治す方法さえ見つかればずっと一緒にいられるからね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_past_4#originalText","id":"talk.vc.home_wait_edith_past_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天我们一起做了很多任务作呢！虽然还有点早，但我们去洗澡吧！","en":"We sure worked hard today! It's a bit early, but let's take a bath!","ja":"今日はふたりでたくさん働いちゃったね!ちょっと早いけど、お風呂にしよう!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_past_5#originalText","id":"talk.vc.home_wait_edith_past_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"取水这种事让我做就好，妳在家好好休息吧。","en":"I'll get the water ready. You just sit down inside and relax.","ja":"水汲みならあたしがやるからあなたはお家で休んでなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_past_6#originalText","id":"talk.vc.home_wait_edith_past_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳煮的饭菜真的很好吃耶，谢谢妳每天做饭给我吃。","en":"Your cooking is always so yummy! I really appreciate it.","ja":"あなたの作るご飯は本当においしいなあいつもありがとうね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_past_7#originalText","id":"talk.vc.home_wait_edith_past_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我得到了可靠的情报！听说有位治疗师连重伤都治得好喔！","en":"Big news! There's this healer who can cure even the most serious of injuries!","ja":"有力な情報を手に入れたわ!大きなケガでも治せるっていう治療師さんがいるんだって!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_past_8#originalText","id":"talk.vc.home_wait_edith_past_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"明天开始，我又要出门一阵子了。……别摆出这种表情嘛，我一定会回到妳身边的。","en":"I'm gonna go out for a while tomorrow... Aw, don't pout. I'll be back before you know it.","ja":"明日から、またちょっと出かけるね……そんな顔しないで。必ずあなたのところに戻ってくるから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_past_9#originalText","id":"talk.vc.home_wait_edith_past_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"哎呀，妳该不会是睡着了吧？呵呵……这样我得抱妳到床上才行呢。","en":"Oh dear, are you asleep already? Hehe... Guess I'll have to carry you to bed.","ja":"あら、もしかして寝ちゃったの?ふふ……それならお布団に運ばないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_past_1#originalText","id":"talk.vc.home_touch_edith_past_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯？不停手也没关系啊，来，再多摸一下吧。","en":"Hm? It's okay, don't stop. Pat my head more. More!","ja":"ん?やめなくていいよほら、もっと撫でて撫でて"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_past_2#originalText","id":"talk.vc.home_touch_edith_past_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不可以把发饰拿下来喔，不然头发会整个炸开的。","en":"Don't take out my ribbon! My hair will fly out everywhere.","ja":"髪飾りほどいちゃダメよ髪の毛がわーって広がっちゃうからね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_past_3#originalText","id":"talk.vc.home_touch_edith_past_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"呵呵，妳的头发很快就会跟我一样长了。到时候我们发型也会是成对呢。","en":"Hehe, don't worry. Yours'll grow as long as mine soon enough. Then we can be twinsies!","ja":"ふふ、すぐにあなたもあたしくらい長くなるわそうしたら、髪型もお揃いね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_past_4#originalText","id":"talk.vc.home_touch_edith_past_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真难得，妳竟然会主动跟我撒娇。好乖好乖，今天就尽情地当个孩子吧。","en":"Aw, you aren't usually this clingy, are you? There, there, I'll indulge you, just for today.","ja":"珍しいわねあなたから甘えてくるなんてよしよし、今日はいっぱい甘えなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_past_5#originalText","id":"talk.vc.home_touch_edith_past_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳该不会是变回小宝宝了吧？呵呵，这样也很可爱呢。","en":"Did you revert to your baby-self? Haha. That's a cute look for you.","ja":"もしかして赤ちゃんに戻っちゃったのかな?ふふ、それもかわいいわね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_past_6#originalText","id":"talk.vc.home_touch_edith_past_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我当然没有不情愿。只是妳这么积极，让我有点吃惊耶。","en":"Of course I don't mind having my hair played with; it just startles me when you tug like that.","ja":"もちろんイヤではないんだけどあんまりグイグイ来られるとちょっとビックリしちゃうわね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_past_7#originalText","id":"talk.vc.home_touch_edith_past_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"咦，我的肚子露出来了吗？不遮好的话可是会感冒呢。","en":"Oops, was my belly showing? Better cover up. Don't wanna catch a cold!","ja":"あれ、おへそ出てた?ちゃんとしまっておかないと風邪引いちゃうもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_past_8#originalText","id":"talk.vc.home_touch_edith_past_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"来，让姊姊抱抱。唉唷，不要畏畏缩缩的，妳可以再过来一点啊。","en":"Here, I'll hold you. Come on now, don't be shy. Just sidle on over!","ja":"ほら、抱っこしてあげるそんな、おっかなびっくりじゃなくてもっとこっちに来ていいんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_1#originalText","id":"talk.vc.home_time_edith_past_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"呼哇……妳醒啦？那我也得起床了呢，毕竟我是姊姊嘛！","en":"Phew... You're awake already? Then I'd better get up too. I'm the big sister, after all!","ja":"ふわあ……もう起きたの?だったら、あたしも起きなくちゃねだってお姉ちゃんだもん!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_2#originalText","id":"talk.vc.home_time_edith_past_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天早上感觉很清爽呢。如果妳的脚状况允许，要不要一起散散步啊？","en":"What a lovely morning. If your foot's feeling fine, want to go on a walk with me?","ja":"今日は気持ちのいい朝ね足の調子がよかったら一緒に散歩しましょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_3#originalText","id":"talk.vc.home_time_edith_past_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"谢谢妳总是帮我准备早餐。每次吃完，都会让我一早就精神百倍呢。","en":"Thanks for always getting my breakfast for me. It always gives me the energy boost I need.","ja":"朝ご飯、いつも用意してくれてありがとう。これを食べると朝から元気が出るんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_4#originalText","id":"talk.vc.home_time_edith_past_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天一整天都要在村里当侍卫。虽然想去旅行，但席亚也很重要嘛。","en":"I'll be helping the guards in the village all day today. Travel is nice, but money is even nicer.","ja":"今日は一日中、村で衛士の手伝いをするの。旅に出たいけどシアも大事だもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_5#originalText","id":"talk.vc.home_time_edith_past_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"至少我在家的期间，得帮忙做好取水这种体力活才行呢。","en":"As long as I'm home, I need to take care of the heavy lifting, like fetching water.","ja":"家にいる間くらいは水汲みなんかの重労働はやってあげないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_6#originalText","id":"talk.vc.home_time_edith_past_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天的视野特别好呢。那个会不会就是尽头山脉啊……","en":"The sky is so clear today! Look how far we can see... Are those the End Mountains?","ja":"今日はずいぶん遠くまで見えるわねあれが果ての山脈かしら……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_7#originalText","id":"talk.vc.home_time_edith_past_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"都这么晚了。为了不让她担心，我得快点回去才行。","en":"It's gotten awfully late... I'd better hurry back. I don't want her to worry.","ja":"ずいぶん遅くなっちゃった心配かけちゃうから急いで帰らないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_8#originalText","id":"talk.vc.home_time_edith_past_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"洗澡水烧好了喔～我们今天也一起洗吧？欸，一起洗嘛？","en":"The bath's all readyyy! Won't you join me today? Pretty-please?","ja":"お風呂湧いたわよー今日も一緒に入ろうよね、いいでしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_9#originalText","id":"talk.vc.home_time_edith_past_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"是不是该睡了啊？来，我也会陪妳一起睡，我们去床上吧。","en":"Isn't it almost time for bed? Come on, off to bed with you. Get the covers warm for me.","ja":"そろそろ寝る時間じゃない?ほら、あたしも一緒に寝るからお布団に行こう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_10#originalText","id":"talk.vc.home_time_edith_past_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……史提西亚大人，希望明天，这孩子的脚可以多少好转一些。","en":"Dear Stacia... Please make her foot feel a little better tomorrow.","ja":"……ステイシア様明日になったら、この子の足が少しでも良くなっていますように"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_11#originalText","id":"talk.vc.home_time_edith_past_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"她一直用这样小小的身子努力撑着……我想找到办法治疗她的脚。","en":"You work so hard every day... You brave little thing... I want to cure your foot.","ja":"こんな小さい体で、いつも頑張って……なんとか足を治してあげたい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_past_12#originalText","id":"talk.vc.home_time_edith_past_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……妳醒了啊？那要不要喝点热牛奶呢？","en":"Can't sleep? Want me to get us some warm milk?","ja":"……目が覚めちゃった?それじゃ、温かいミルクでも飲みましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_past_11#originalText","id":"talk.vc.home_day_edith_past_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"就算假期结束，妳依然很有活力呢。托妳的福，我也觉得自己充满活力。","en":"Even the first day back from vacation, you're full of energy. Glad it's rubbing off on me!","ja":"休み明けでも、あなたは元気だね。おかげであたしも元気になってきちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_past_12#originalText","id":"talk.vc.home_day_edith_past_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"踏上旅途后，就会有好一段时间见不到妳，所以我想趁现在多跟妳相处。","en":"When I leave on my quest, I won't see you for a while. So I want to see you as much as I can now.","ja":"旅に出たら、しばらく会えなくなっちゃうからね。今はできるだけ一緒にいたいの"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_past_13#originalText","id":"talk.vc.home_day_edith_past_13","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"安息日终于到了！让我们悠悠哉哉地休养吧。","en":"Finally, a Day of Rest! Let's lie around, do nothing, and recharge.","ja":"やっと安息日だね!のんびり、ゆっくり疲れを癒やそうね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_past_14#originalText","id":"talk.vc.home_day_edith_past_14","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"安息日玩得开心吗？明天开始再一起努力吧！但妳千万不能勉强自己喔。","en":"Did you enjoy your Day of Rest? Let's put in another good week's work! In moderation, of course.","ja":"安息日は楽しかった?明日から、また頑張りましょう!でも無理は禁物だからね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_1#originalText","id":"talk.vc.home_event_edith_past_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"新年快乐！真高兴今年也能和妳一起迎接新的一年呢。","en":"Happy New Year! I hope we get to spend a lot of time together, like last year.","ja":"新年おめでとう今年もあなたと一緒に迎えられてうれしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_2#originalText","id":"talk.vc.home_event_edith_past_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"听说异国在这一天有撒豆的习俗，好像是为了驱逐魔物呢。","en":"I hear they throw beans this time of year in other countries. It's to ward off evil, apparently.","ja":"異国では、この日に豆をまく風習があるんだって魔物を追い払うみたいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_3#originalText","id":"talk.vc.home_event_edith_past_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天一起来做点心吧。听说啊，今天好像就是这种日子！","en":"Let's make some candy together! Apparently, that's what you're supposed to do today.","ja":"今日は一緒にお菓子を作りましょうなんか、そういう日なんだって!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_4#originalText","id":"talk.vc.home_event_edith_past_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"听说今天是属于女孩子的庆典。既然这样，有我跟妳，就得一次祝贺两人份才行呢。","en":"It's a festival for girls today, apparently. We'll need to celebrate for the both of us, I guess!","ja":"今日は女の子のお祭りだってだったら、あなたとあたしふたり分のお祝いしないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_5#originalText","id":"talk.vc.home_event_edith_past_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"实际上好像是男生给女生回礼的样子，但女生之间互送也没关系吧。","en":"It's supposed to be a day of boys giving girls gifts, but I'm sure it's okay that we're both girls.","ja":"本当なら、男の子から女の子へ贈り物のお返しをするみたいだけど別に女の子同士でもいいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_6#originalText","id":"talk.vc.home_event_edith_past_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"说谎还是不好啊，而且会对这孩子的教育产生不良影响。","en":"I just can't approve of lying. I don't want her to pick up any bad habits.","ja":"やっぱり、嘘はよくないわこの子の教育にだって悪い影響が出ちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_7#originalText","id":"talk.vc.home_event_edith_past_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"久违的长假，我们找个地方出趟小远门吧？不用担心，有我负责背妳。","en":"Want to travel someplace far away for our vacation? Don't worry, I'll carry you.","ja":"久しぶりの長いお休みどこか少し遠くへ行こうか大丈夫、あたしがおんぶするから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_8#originalText","id":"talk.vc.home_event_edith_past_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"下雨不是问题，但持续这么久就叫人担心了。希望麦子没有泡烂。","en":"I don't mind the rain... I just wish it'd stop soon. I hope the wheat doesn't rot.","ja":"雨も悪くないけど、こう長く続くと心配ね麦が枯れなければいいけど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_9#originalText","id":"talk.vc.home_event_edith_past_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"愿望？这还用说，当然是妳的健康啊。","en":"What's my wish? Isn't it obvious? Your health, of course.","ja":"お願いごと?そんなの決まってるじゃないあなたの健康よ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_10#originalText","id":"talk.vc.home_event_edith_past_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"马上就是夏至祭典了呢，今年我们一起参加，然后玩个痛快吧！","en":"The Summer Festival's almost here! Let's go together this year! I'm in the mood to party!","ja":"もうすぐ夏至祭ね今年は一緒に行こうよそして、たくさん遊びましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_11#originalText","id":"talk.vc.home_event_edith_past_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"暑假就到今天为止了，唉～好想再跟妳多玩几天喔。","en":"Aw, summer vacation ends today. Arrrgh. There's still so many things I wanted to do with you.","ja":"夏のお休み、今日で終わっちゃうあーあ、もっと一緒に遊びたかったなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_12#originalText","id":"talk.vc.home_event_edith_past_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"露那利亚大人有种不同于索鲁斯大人的静谧之美呢。","en":"Lunaria has a sort of quiet beauty that Solus lacks.","ja":"ルナリア様は、ソルス様とはまた違った、静かな美しさがあるのよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_13#originalText","id":"talk.vc.home_event_edith_past_13","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"听说今天要发糖果给小孩子。所以呢，这是我要送妳的礼物。","en":"You're supposed to give kids candy today. So here's some candy!","ja":"今日は子どもたちに、お菓子をあげるんだって。だからねあたしからあなたに、贈り物"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_past_15#originalText","id":"talk.vc.home_event_edith_past_15","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"听说今天是家人一起吃大餐的日子。我会负责准备食材，烹调就拜托妳了。","en":"Today's a day of feasting with the family! I'll get the ingredients if you take care of the cooking.","ja":"今日は家族でご馳走を一緒に食べる日なんだって。材料はあたしが用意するから、料理お願い"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_past_1#originalText","id":"talk.vc.home_etc_edith_past_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"工作辛苦了，稍微休息一下吧。休息过后，再继续努力加油！","en":"Good work so far! Put your feet up and rest a bit...so that we can get out there again!","ja":"お仕事お疲れさま少し休みましょうそれから、また頑張ろうね!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_past_2#originalText","id":"talk.vc.home_etc_edith_past_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好像有礼物！我想里面肯定有妳想要的东西喔。","en":"Ooh, a present! I'm sure it's something you've always wanted.","ja":"贈り物だって!きっとあなたが欲しいものが入っていると思うわ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_past_3#originalText","id":"talk.vc.home_etc_edith_past_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"下个工作来了啊……可别硬撑喔，要是遇上困难，我也会帮忙的。","en":"A new mission, eh? Well... don't kill yourself over it, okay? I'll be there if you need help.","ja":"次のお仕事か……あんまり無理はしないでね困ったら、あたしも手伝うから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_sao_1#originalText","id":"talk.vc.home_wait_mito_sao_1","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你来了啊，太好了……","en":"Oh, good. You're here.","ja":"来てくれたのねよかった……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_sao_2#originalText","id":"talk.vc.home_wait_mito_sao_2","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"成功回去另一边之后，我想去电子游乐场。不知道出了哪些新的游戏了。","en":"I'd love to go to the arcade when we get back. I want to scope out the new games.","ja":"向こうに戻れたらゲームセンターに行きたいわ新作が気になるから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_sao_3#originalText","id":"talk.vc.home_wait_mito_sao_3","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"竟然要顶着没化妆的脸玩，好害羞啊……","en":"Play a character with my real face showing? Too awkward...","ja":"素顔でプレイするなんて気恥ずかしいわ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_sao_4#originalText","id":"talk.vc.home_wait_mito_sao_4","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你要是没事做的话，要不要来讨论一下如何提高练功的效率？","en":"If you're free, wanna discuss how we might increase our hunting success rate?","ja":"暇なら狩り効率を上げる方法について議論しましょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_sao_5#originalText","id":"talk.vc.home_wait_mito_sao_5","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你应该要更重视攻击，聚精会神，等待出手的机会。","en":"You focus on offense, okay? Sharpen your senses and look for your opportunity.","ja":"貴方はもっと、攻めを重視してね心を研ぎ澄まして機会を窺うの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_sao_6#originalText","id":"talk.vc.home_wait_mito_sao_6","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"没事吧？你看起来一脸疲惫。","en":"You okay? You look tired.","ja":"大丈夫?疲れた顔よ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_sao_7#originalText","id":"talk.vc.home_wait_mito_sao_7","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"我很高兴，在SAO也能见到你……","en":"Even though we have to be in SAO, I'm still glad I met you.","ja":"SAOでも貴方に会えて嬉しいわ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_sao_8#originalText","id":"talk.vc.home_wait_mito_sao_8","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"小心，不要误判撤退时机。这才是最重要的。","en":"Don't quit prematurely. That's the most important thing to remember.","ja":"退きどきを見誤らないようにねそれが一番大事"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_sao_9#originalText","id":"talk.vc.home_wait_mito_sao_9","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"要不要再聊一下？我找到一家好吃的店。","en":"Wanna hang out a bit more? I know this great restaurant.","ja":"もう少し話をしない?美味しいお店を見つけたから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_sao_1#originalText","id":"talk.vc.home_touch_mito_sao_1","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"想要我帮你弄头发？那你去坐在那边。","en":"You want me to touch your hair? Then sit down.","ja":"髪をいじって欲しいの?そこに座って"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_sao_2#originalText","id":"talk.vc.home_touch_mito_sao_2","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"唉唷……怎样啦……","en":"Jeez... What?","ja":"もう……何……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_sao_3#originalText","id":"talk.vc.home_touch_mito_sao_3","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"有种怪怪的感觉……","en":"This feels...weird.","ja":"何だか、変な感じ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_sao_4#originalText","id":"talk.vc.home_touch_mito_sao_4","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"喂……！","en":"Hey, pal...!","ja":"ちょっと……!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_sao_5#originalText","id":"talk.vc.home_touch_mito_sao_5","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你给我差不多一点，不然我要注销了。……虽然想出去也办不到。","en":"If you don't cut that out, I'm logging out! Man...if only.","ja":"いい加減にしないとログアウトするわよ……できないけれど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_sao_6#originalText","id":"talk.vc.home_touch_mito_sao_6","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"又这样撒娇……","en":"Again with the puppy dog eyes...","ja":"また、そんなおねだりして……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_sao_7#originalText","id":"talk.vc.home_touch_mito_sao_7","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"真是的！我看起来像是会让人撒娇的类型吗！？","en":"Hey! Do I look like the affectionate type?!","ja":"もうっ!私が、甘えられるようなタイプに見える!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_sao_8#originalText","id":"talk.vc.home_touch_mito_sao_8","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"啊～你很闲吗？那就去练功吧。","en":"Ohhh, I get it. You're bored. Okay, let's go hunting.","ja":"あー、暇なのね?なら、狩りに行くわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_1#originalText","id":"talk.vc.home_time_mito_sao_1","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你起床啦？那我们赶快去练功吧。","en":"You awake? Then let's get right to hunting.","ja":"起きた?なら、さっそく狩りに行きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_2#originalText","id":"talk.vc.home_time_mito_sao_2","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"早安。看你睡眼惺忪的……呵呵。","en":"Good morning. Aww, you've got sleepy eyes.","ja":"おはよう寝ぼけまなこね……ふふ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_3#originalText","id":"talk.vc.home_time_mito_sao_3","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"快去洗把脸。顶着这张脸，连恐狼都打不倒的。","en":"Go wash your face. You won't even defeat a dire wolf, looking like that.","ja":"顔を洗ってきなさいそんな顔じゃダイアー・ウルフだって倒せないわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_4#originalText","id":"talk.vc.home_time_mito_sao_4","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"午餐？真麻烦。不知道SAO有没有类似能量棒之类的东西……","en":"Lunch? What a hassle. I wonder if SAO has cereal bars?","ja":"昼食? 面倒ねシリアルバー的なものはSAOにないのかしら……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_5#originalText","id":"talk.vc.home_time_mito_sao_5","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"肚子饿了？那我带你去吃好料。","en":"Are you hungry? Let me take you out to lunch. I know a great place.","ja":"お腹が減ったの?美味しいところに連れていってあげるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_6#originalText","id":"talk.vc.home_time_mito_sao_6","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"中午练功区没人，就是要趁这时候去。","en":"Hunting grounds clear up around lunchtime. And I'm counting on that.","ja":"お昼で狩り場が空くからそこが狙いどきよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_7#originalText","id":"talk.vc.home_time_mito_sao_7","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"我喜欢晚上，因为练功比较有效率。","en":"I love night time. Easier to hunt then.","ja":"夜は好きよ狩りが捗るから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_8#originalText","id":"talk.vc.home_time_mito_sao_8","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"黑暗的地方，感觉就是会有什么东西跑出来……","en":"When it's pitch-black like this, it really makes you believe in ghosts...","ja":"暗闇って何か出そうよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_9#originalText","id":"talk.vc.home_time_mito_sao_9","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"原来SAO也有星空呢。好漂亮啊。","en":"I love how even SAO has stars. They're so pretty.","ja":"SAOにも星空があるのねとても綺麗だわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_10#originalText","id":"talk.vc.home_time_mito_sao_10","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"已经要说晚安了？攻略不是还没完成吗？","en":"You're going to sleep already? But aren't there more raids to do?","ja":"もう、おやすみなさいを言うの?まだ攻略が残っているでしょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_11#originalText","id":"talk.vc.home_time_mito_sao_11","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"困了？真拿你没办法……","en":"Sleepy? Okay, fine...","ja":"眠い?仕方ないわね……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_sao_12#originalText","id":"talk.vc.home_time_mito_sao_12","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"喔，睡觉时间……难道就不能帮我们更新成不用睡觉的模式吗？","en":"Argh, bedtime... I wish they'd install an update that makes us not need sleep.","ja":"ああ、寝る時間……寝なくてもいい仕様にアップデートしてくれないかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mito_sao_1#originalText","id":"talk.vc.home_day_mito_sao_1","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"一个礼拜开始了。我们要在这个礼拜内把等级升上去。","en":"A new week, new beginnings. Let's level up by the weekend.","ja":"週の始まりね今週中にはレベルアップしましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mito_sao_2#originalText","id":"talk.vc.home_day_mito_sao_2","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你好像很忙呢。其实也没差……反正你都有来见我。","en":"You seem busy. You didn't have to come... But I still appreciate it.","ja":"忙しそうね別にいいけど……こうして逢いに来てくれているし"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mito_sao_3#originalText","id":"talk.vc.home_day_mito_sao_3","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你今天休息？所以过来找我吗？我好高兴。","en":"It's your day off? Oh, so that's why you showed up. Thanks. That's really nice.","ja":"休日?それで来たのね嬉しいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mito_sao_4#originalText","id":"talk.vc.home_day_mito_sao_4","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"我想要……再跟你待一会。","en":"I just wanted to spend... a little more time with you.","ja":"もう少し……貴方と一緒にいたかったわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_1#originalText","id":"talk.vc.home_event_mito_sao_1","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"新年快乐。然后呢？新年第一个练功区要选在哪里？","en":"Happy New Year! Where do you want to make your first hunt of the year?","ja":"あけましておめでとうそれで、新年初狩り場はどこにする?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_2#originalText","id":"talk.vc.home_event_mito_sao_2","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"豆子算是投掷类的武器吗？","en":"Do beans count as a ranged weapon?","ja":"豆は投擲武器カテゴリかしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_3#originalText","id":"talk.vc.home_event_mito_sao_3","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"来，这个送你。虽然我一直以来多半是收下巧克力的那一方……","en":"Here. Chocolate. Though I must say, I'm more used to being on the receiving end.","ja":"はい、これ昔から、チョコはもらう機会の方が多かったけれど……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_4#originalText","id":"talk.vc.home_event_mito_sao_4","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"关于女儿节娃娃的回忆吗？我小时候总觉得「那衣服看起来好难活动」。","en":"I remember Hinamatsuri dolls. When I was little, I thought their clothes looked very uncomfortable.","ja":"雛人形の思い出ね子供心に「動きづらそうな服」って思っていたわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_5#originalText","id":"talk.vc.home_event_mito_sao_5","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"……要给我吗？谢谢……","en":"Is that for me? Thanks...","ja":"……くれるの?ありがとう……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_6#originalText","id":"talk.vc.home_event_mito_sao_6","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"我没办法骗人的。……骗你的。","en":"I cannot tell a lie... Yeah, that's a lie.","ja":"私、嘘はつけないの……嘘よ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_7#originalText","id":"talk.vc.home_event_mito_sao_7","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"假期开始了。我们去练功吧。","en":"We've got some time off. Wanna go hunting?","ja":"お休みね狩りに行きましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_8#originalText","id":"talk.vc.home_event_mito_sao_8","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"地上都是烂泥巴，没办法好好打怪练等。真是令人忧郁的季节……","en":"The ground's too marshy to plant my feet for a good shot. Don't you just love rainy season?","ja":"足下がぬかるんでうまく狩れない憂鬱なシーズンね……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_9#originalText","id":"talk.vc.home_event_mito_sao_9","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"织女是天琴座α，牛郎是天鹰座α，挡在他们之间的河就是银河。","en":"Orihime is Vega, Hikoboshi is Altair, and \"Heaven's river\" is the Milky Way.","ja":"織姫がベガ彦星はアルタイル天の川はミルキーウェイよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_10#originalText","id":"talk.vc.home_event_mito_sao_10","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"要去海边？这样武器不会生锈吗……","en":"You're going to the beach? Hope your weapons don't rust in the ocean...","ja":"海に行くの?武器が錆びないかしら……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_11#originalText","id":"talk.vc.home_event_mito_sao_11","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"夏天的尾声总是让人感到寂寞呢。","en":"The end of summer always makes me feel a bit melancholy.","ja":"夏の終わりって物寂しいわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_12#originalText","id":"talk.vc.home_event_mito_sao_12","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你觉得月亮的纹路看起来像什么？我一点都不觉得像兔子。","en":"What do you think the moon craters look like? 'Cause I just don't see a rabbit.","ja":"月の模様って何に見える?私はウサギに見えないのよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_13#originalText","id":"talk.vc.home_event_mito_sao_13","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"不知道那个南瓜丢出去能不能造成伤害。","en":"That pumpkin looks hard. I wonder how much damage it would inflict if thrown?","ja":"あのカボチャ投げたらダメージを与えられないかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_14#originalText","id":"talk.vc.home_event_mito_sao_14","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"要是那天我没有邀亚丝娜的话……","en":"If only I hadn't asked Asuna to come with me that day...","ja":"あの日アスナを誘っていなければ……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_sao_15#originalText","id":"talk.vc.home_event_mito_sao_15","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"这样的日子，你跟我在一起没关系吗？","en":"Are you sure you're okay with spending a special day like this with me?","ja":"こんな日に、私と一緒にいて貴方はそれでいいの……?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_mito_sao_1#originalText","id":"talk.vc.home_season_mito_sao_1","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"真想……再看看樱花。","en":"Cherry blossoms... That's something I definitely hope to see again.","ja":"桜の花……また見たいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_mito_sao_2#originalText","id":"talk.vc.home_season_mito_sao_2","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"我讨厌炎热，因为手汗会让掌心好滑。","en":"I hate hot summer days. Too much slippery sweat.","ja":"暑いのは嫌いよ手汗で滑るから"},"kind":"dialogue"},{"uid":"talk.vc.home_season_mito_sao_3#originalText","id":"talk.vc.home_season_mito_sao_3","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"不知道有没有哪个楼层有美丽的枫叶？","en":"Do any of these levels have pretty red leaves in the fall?","ja":"紅葉の美しい階層ってあったかしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_mito_sao_4#originalText","id":"talk.vc.home_season_mito_sao_4","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"我讨厌寒冷，因为手指会冻僵。","en":"I hate the cold. My fingers get all stiff.","ja":"寒いのは嫌いよ指がかじかむから"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_mito_sao_1#originalText","id":"talk.vc.home_rank_mito_sao_1","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你升级了呢。很努力嘛。","en":"You just ranked up. Congrats. You earned it.","ja":"ランクアップね頑張ったじゃない"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_mito_sao_2#originalText","id":"talk.vc.home_rank_mito_sao_2","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"不错嘛，继续保持。","en":"That's good. Keep at it.","ja":"いいわね。その調子よ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_mito_sao_3#originalText","id":"talk.vc.home_rank_mito_sao_3","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你最近变得判若两人呢。","en":"I hardly recognize you anymore.","ja":"最近、見違えたわね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_mito_sao_4#originalText","id":"talk.vc.home_rank_mito_sao_4","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"你就是我的目标。","en":"I strive to be like you.","ja":"貴方が、私の目標よ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_mito_sao_5#originalText","id":"talk.vc.home_rank_mito_sao_5","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"我会追着你的背影前进。","en":"I'm going to keep pace with you. Hope you don't mind.","ja":"その背中追いかけさせてもらうわ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_mito_sao_1#originalText","id":"talk.vc.home_etc_mito_sao_1","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"达成使命了，你很行嘛。","en":"Mission accomplished. Not too shabby.","ja":"ミッション達成ねやるじゃないの"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_mito_sao_2#originalText","id":"talk.vc.home_etc_mito_sao_2","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"有礼物送来了。不要放到忘记，早点去看看吧。","en":"You've got a present. Open it before you forget.","ja":"プレゼントが届いているわ忘れないうちに確認よ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_mito_sao_3#originalText","id":"talk.vc.home_etc_mito_sao_3","speaker":{"cn":"米特","en":"Mito","ja":"ミト"},"text":{"cn":"好像有新任务呢。来，我们走吧。","en":"I hear a new Quest just came in. Come on, let's check it out.","ja":"新しいクエストがあるみたいねほら、行きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_progre_1#originalText","id":"talk.vc.home_wait_asuna_sao_progre_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"姑且跟你道一声谢。如果我那时倒下的话，就不会像现在这样活在这里了。","en":"Thank you. I do owe you that. If you hadn't helped me up back then, I wouldn't be alive today.","ja":"一応、お礼は言っておくわあの時倒れていたら、今こうして生きていることはなかったから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_progre_2#originalText","id":"talk.vc.home_wait_asuna_sao_progre_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"虽然我们现在组了队，但这只是暂时的，你可不要误会了。","en":"We may be in a party together now, but our alliance is temporary. Don't forget that.","ja":"今はこうしてパーティー組んでるけどあくまで一時的だから勘違いしないでよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_progre_3#originalText","id":"talk.vc.home_wait_asuna_sao_progre_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不管在哪个世界，都会有想当老大的人冒出来呢。你好像不是那种人就是了。","en":"I suppose control freaks exist everywhere, don't they. Though you don't seem like one.","ja":"仕切りたがる人が出てくるのはどこの世界でも一緒ね。君はそういうタイプじゃないみたいだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_progre_4#originalText","id":"talk.vc.home_wait_asuna_sao_progre_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"进入这个世界明明还没有多久，现实生活却好像已经是很久以前的事了。","en":"Not much time has passed since I've come here, but the real world already feels like a distant memory.","ja":"この世界に入ってまだそんなに時間が経ってないのにリアルが遠い昔のように感じるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_progre_5#originalText","id":"talk.vc.home_wait_asuna_sao_progre_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我重视武器的命中率，是因为这样比较有效率。不论战斗还是念书，效率都很重要吧？","en":"I put so much care into calibrating my weapons because I value efficiency. In battle and in school.","ja":"武器の正確さを重視するのはそれが効率がいいからよ戦いも勉強も、効率が大事でしょ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_progre_6#originalText","id":"talk.vc.home_wait_asuna_sao_progre_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"为了活下去，吃饭也是很重要的。你教会了我这个道理。","en":"You need to eat to survive. You taught me that.","ja":"生きていくためには、ご飯も大事あなたに、そのことを教わったの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_progre_7#originalText","id":"talk.vc.home_wait_asuna_sao_progre_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"比起攻略情报，我更在意有没有浴室或奶油这类的事情……","en":"Baths and cream... I guess I care more about that sort of news than battle intel.","ja":"お風呂とかクリームとか……わたしは攻略情報よりもそっちの情報の方が気になるな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_progre_8#originalText","id":"talk.vc.home_wait_asuna_sao_progre_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"跟一开始相比，大家变得开朗多了呢。或许要归功于某人让游戏有所进展吧。","en":"Everyone's happier than they were at first. Maybe because somebody's been helping us make progress.","ja":"最初の頃と比べると、みんな明るくなったよね。誰かさんのおかげでゲームが前に進んだからかも"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_progre_9#originalText","id":"talk.vc.home_wait_asuna_sao_progre_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……你该不会以为那个变装骗得了人吧？超级明显的啊。","en":"Wait... Did you honestly think that disguise would fool me? It's painfully obvious.","ja":"……もしかして、そんな変装でごまかせてると思ってるの?バレバレなんですけど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_progre_1#originalText","id":"talk.vc.home_touch_asuna_sao_progre_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"等、等一下！不要随便摸我的头发！就算这是在游戏里面……","en":"H-Hey! Don't touch my hair! I know we're in a game, but that's no excuse.","ja":"ちょ、ちょっと!気軽に髪の毛触んないでよ!いくらゲームの中だからって……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_progre_2#originalText","id":"talk.vc.home_touch_asuna_sao_progre_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"戴着沉重的头盔不会很难战斗吗？视野变窄的话，应该很容易受到偷袭吧？","en":"Wouldn't fighting in a heavy helmet just blind me and make me more vulnerable to sudden attacks?","ja":"重たい兜って戦いにくくないのかな視界が狭くなると、不意打ちを受けやすくなりそうじゃない?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_progre_3#originalText","id":"talk.vc.home_touch_asuna_sao_progre_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不用在意痘痘或者皮肤干燥，是这个世界为数不多的优点。","en":"Not needing to worry about pimples or dry skin is one of the few perks of being trapped in this world.","ja":"ニキビとか肌荒れを気にしなくていいのは、数少ないこの世界のいいところね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_progre_4#originalText","id":"talk.vc.home_touch_asuna_sao_progre_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……你可能忘记了，不过这个游戏是有《伦理规范》系统存在的。","en":"I suppose you've forgotten, but... you do realize this game has an ethics code, right?","ja":"……お忘れかもしれないけどこのゲームには《倫理コード》っていうシステムがあるんですけど?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_progre_5#originalText","id":"talk.vc.home_touch_asuna_sao_progre_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……你该不会是想被我揍吧？还是比较想要我用剑砍？","en":"Wait... Do you want me to hit you? Or would you rather I cut you with my sword?","ja":"……もしかして、わたしに殴られたいの? それとも剣で斬られる方をお望みかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_progre_6#originalText","id":"talk.vc.home_touch_asuna_sao_progre_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"刚才那个我就当作是不可抗力放你一马。不准有第二次。","en":"I'll believe \"the devil made you do it\" and let that slide... But don't let it ever happen again.","ja":"今のは、不可抗力ってことで見逃してあげる二度目はないからね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_progre_7#originalText","id":"talk.vc.home_touch_asuna_sao_progre_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要穿防御力高的盔甲就得增加肌肉才行。但我不太想练得很健壮……","en":"I can't use high-defense armor without increasing my strength first. But I don't want to get buff...","ja":"防御力の高い鎧は筋力を上げないといけないのよねムキムキになるのは、ちょっと……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_progre_8#originalText","id":"talk.vc.home_touch_asuna_sao_progre_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"其实我想穿时髦一点的衣服。如果去到上面的楼层不知道会不会有？","en":"Truth be told, I'd rather wear something more fashionable. Think the higher levels have nicer clothes?","ja":"本当は、もう少しお洒落な服を着たいんだけどね。上の階に行けばそういうのもあるのかな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_1#originalText","id":"talk.vc.home_time_asuna_sao_progre_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就算是在游戏里，我也想尽量过规律的生活。那样子身心状态也会比较好。","en":"Even though we're trapped in a game, I'd still like some routine to my life. It just feels better.","ja":"ゲームの中でも、できれば規則正しく生活したいわよねその方が気分もいいし"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_2#originalText","id":"talk.vc.home_time_asuna_sao_progre_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"早上的太阳好刺眼。竟然连这部分都做得这么逼真，有点难以置信。","en":"The sun's so bright my eyes hurt. It's hard to believe they were able to replicate that with such detail.","ja":"朝日がまぶしくて目が痛いそんなところまで再現できるなんてちょっと信じられないけど"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_3#originalText","id":"talk.vc.home_time_asuna_sao_progre_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"早上起来就会反射性地想着要换制服。会不会过没多久，连这个习惯都消失了呢？","en":"Whenever I wake up, I instinctively reach for my school uniform. Do you think that will stop over time?","ja":"朝起きると、反射的に制服に着替えなきゃって思っちゃうそのうち、これもなくなるのかな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_4#originalText","id":"talk.vc.home_time_asuna_sao_progre_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"没有料理技能，连想要自己煮饭都办不到呢。我是不是该来练一下呢？","en":"Without cooking skills, I can't even feed myself. Maybe I should change that.","ja":"調理スキルがないと自炊もできないんだね少し上げてみようかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_5#originalText","id":"talk.vc.home_time_asuna_sao_progre_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我试着找了一下，结果真的没有类似学校的地方。也对啦，毕竟是在游戏里面。","en":"I looked around, but there just aren't any schools in this game. Guess that makes sense, though.","ja":"少し探してみたけど、やっぱり学校みたいなところってないわねゲームの中だし、当たり前か"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_6#originalText","id":"talk.vc.home_time_asuna_sao_progre_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"从城镇进入《圈外》时，我还是会有点紧张。毕竟这真的是攸关性命。","en":"I can't help but feel nervous whenever I go \"out of range.\" I'm literally putting my life in danger.","ja":"街の中から《圏外》に出る時はやっぱり少し緊張する文字通り、命がかかってるもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_7#originalText","id":"talk.vc.home_time_asuna_sao_progre_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我在现实世界晚上不太会待在外面，所以现在总有一种在做坏事的感觉。","en":"I never used to walk at night IRL anyway, so I always feel unsafe.","ja":"夜に街を歩くなんて、リアルではあんまりしなかったからなんか悪いことをしてる気分"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_8#originalText","id":"talk.vc.home_time_asuna_sao_progre_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"有人会喝酒，不过在游戏里面也有办法喝醉吗？","en":"Whenever I see people drinking, I wonder if it's possible to get drunk in this game.","ja":"お酒を飲んでる人たちがいるけどゲームの中でもちゃんと酔えるのかな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_9#originalText","id":"talk.vc.home_time_asuna_sao_progre_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"晚上的《圈外》很可怕。而且一片漆黑，什么都看不到……你最好也不要外出。","en":"Leaving the safe areas at night is terrifying. It's pitch black, for one thing... So try to avoid it.","ja":"夜の《圏外》は怖いね真っ暗で何も見えないし……君も外に出ない方がいいわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_10#originalText","id":"talk.vc.home_time_asuna_sao_progre_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"差不多该睡了吧。就算是在游戏里面，熬夜也对身体不好。","en":"We should get to bed. Even though our bodies aren't technically here, all-nighters are still bad for us.","ja":"そろそろ寝ましょうよいくらゲームの中だからって夜更かしは体に毒だと思うわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_11#originalText","id":"talk.vc.home_time_asuna_sao_progre_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我本来以为玩在线游戏的人都喜欢熬夜，不过这里大部分的人晚上都会睡觉呢。","en":"I assumed online gamers all played late into the night, but most people are asleep right now.","ja":"オンラインゲームの人たちってみんな深夜に遊んでると思ってたでも、夜はほとんどの人が寝るんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_progre_12#originalText","id":"talk.vc.home_time_asuna_sao_progre_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……你也睡不着吗？其实我也是。要不要来聊一下天？","en":"You can't sleep? Neither can I. Want to chat for a bit?","ja":"……君も眠れないの?実はわたしもなのなら、ちょっとおしゃべりしようか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_progre_1#originalText","id":"talk.vc.home_day_asuna_sao_progre_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"待在这个世界，星期一都不像星期一了。果然是因为不用上学也不用上班吗？","en":"In this world, Mondays just don't feel the same. Probably because there's no school or work.","ja":"この世界にいると月曜日って感じがしないねやっぱり学校も会社もないからかな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_progre_2#originalText","id":"talk.vc.home_day_asuna_sao_progre_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"跟现实世界比起来，这里的每一天的确很刺激。虽然有时候刺激过头了。","en":"Our daily life here is definitely much more intense than in the real world. Too intense at times, though...","ja":"リアルに比べると、確かに毎日が刺激的ではあるわねちょっと過激すぎるところもあるけど"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_progre_3#originalText","id":"talk.vc.home_day_asuna_sao_progre_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"跟另一边不同，六日可不能放假不攻略呢。今天也要好好努力！","en":"Unlike the real world, we don't get to take weekends off here. Another day, another raid!","ja":"向こうと違って、土日は攻略お休みなんてわけにはいかないもんね今日も頑張らないと!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_progre_4#originalText","id":"talk.vc.home_day_asuna_sao_progre_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"明天开始又是新的一周。每个星期天的晚上，我都会这样提醒自己。","en":"Another week begins tomorrow... Sunday nights always make me hyper-aware of that.","ja":"明日からまた、新しい週が始まるって、日曜の夜はあえて意識するようにしてるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_progre_1#originalText","id":"talk.vc.home_event_asuna_sao_progre_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"新年快乐。我从没想过会在游戏里面跟人拜年。","en":"Happy New Year. I never pictured myself ringing in the new year inside a game.","ja":"あけましておめでとうまさかゲームの中で新年の挨拶をするなんて、思ってもみなかったな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_progre_2#originalText","id":"talk.vc.home_event_asuna_sao_progre_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"难得过节，我也想要撒豆子。但是豆子撒出去，耐久值会不会降低啊？","en":"I'd love to throw beans for Setsubun, but would the beans' DEF go down after they're thrown?","ja":"せっかくだから豆まきもしたいけどばらまいたら豆の耐久値がなくなったりしないかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_progre_3#originalText","id":"talk.vc.home_event_asuna_sao_progre_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就连手工巧克力也要提升技能才有办法做啊。如果谈了恋爱，会很辛苦吧。","en":"You can't make chocolate here without a high enough Cooking skill. In-game romance sure is tough.","ja":"手作りチョコレートもスキルを上げないと作れないんだ恋愛とかしたら、大変そう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_progre_4#originalText","id":"talk.vc.home_event_asuna_sao_progre_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"虽然SAO里面女生很少，不过至少在女儿节这天，想跟大家聚在一起开开心心地聊天。","en":"There aren't many girls in SAO, but I'd love to get a group together to celebrate Hinamatsuri.","ja":"SAOには女の子が少ないけどひな祭りくらいみんなで集まってわいわいおしゃべりしたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_progre_5#originalText","id":"talk.vc.home_event_asuna_sao_progre_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你在白色情人节有要送谁回礼吗？……我是没有很在意啦。","en":"So, are you giving any girls thank you gifts for White Day? Not like that matters or anything...","ja":"君には、ホワイトデーにお返しをあげる人がいるの?……別に気になるわけじゃないけど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_progre_6#originalText","id":"talk.vc.home_event_asuna_sao_progre_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"愚人节吗……我还真希望被卷入这个游戏是哪个人开的玩笑。","en":"April Fools' Day, huh? I wish this game were just some big elaborate practical joke.","ja":"エイプリルフール、ねえ……このゲームに巻き込まれたことが何かの冗談であってほしいわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_progre_7#originalText","id":"talk.vc.home_event_asuna_sao_progre_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这么说来，我以前黄金周都一直在念书，像这样待在户外感觉有点新奇。","en":"I used to spend Golden Week buried in homework, so being outside like this is actually new to me.","ja":"そう言えば、ゴールデンウィークは勉強ばかりしてたからこうやって外にいるのは新鮮かも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_progre_8#originalText","id":"talk.vc.home_event_asuna_sao_progre_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"六月新娘应该和我无关吧。实在很难想像在游戏里面结婚。","en":"June is for brides, but not for me. I can't even think about marriage when I'm stuck in this game.","ja":"ジューンブライドだけど、わたしには関係ないかな。ゲームの中で結婚なんて考えられないもの"},"kind":"dialogue"}]};
